import Link from "next/link";
import Image from "next/image";

export default function Home() {
  return (
    <div className="flex flex-col flex-1 items-center justify-center min-h-screen bg-zinc-700 text-white font-sans p-8">
      <main className="flex flex-col item-center justify-center max-w-xl text-center gap-6">
        {/* Logo del proyecto */}
        <Image
          className="h-20 w-auto object-contain"
          src="/barco.png"
          alt=" logo"
          width={120}
          height={40}
          priority
        />

        <h1 className="text-3xl font-semibold text-black dark:text-zinc-50">
          Bienvenido a Sobereign Node
        </h1>
        <p className="text-lg text-zinc-600 dark:text-zinc-400">
          Selecciona una opción para comenzar.
        </p>

       
        <div className="flex flex-col sm:flex-row items-center justify-center gap-4">
          <Link
            href="/registro"
            className="rounded-full bg-foreground text-background px-6 py-3 font-medium hover:bg-[#383838] dark:hover:bg-[#ccc] transition-colors text-center"
          >
            Crear Recibo
          </Link>
          <Link
            href="/perfil"
            className="rounded-full border border-zinc-300 dark:border-zinc-700 px-6 py-3 font-medium hover:bg-zinc-100 dark:hover:bg-zinc-900 transition-colors text-center"
          >
            Ver Facturas
          </Link>
        </div>
      </main>
    </div>
  );
}
